-- The legacy enter(pi) function is kept as written;
-- scripts/legacy/portal_driver.lua supplies pi and runs it.
baseid = 106021000
dungeonid = 106021001
dungeons = 10

function enter(pi)
    local i
    if (pi.getMapId() == baseid) then
        i = 0
        while (i < dungeons) do
            if (pi.getPlayerCount(__add(dungeonid, i)) == 0) then
                pi.warp(__add(dungeonid, i), 0)
                do return true end
            end
            i = i + 1
        end
        pi.playerMessage(5, "All of the Mini-Dungeons are in use right now, please try again later.")
        do return false end
    else
        pi.warp(baseid, "in00")
    end
    do return true end
end
